solution.tree_building.zig:
const std = @import("std");
pub const Record = struct { id: usize, parent: usize };
pub const Node = struct { id: usize, children: std.array_list.Managed(*Node) };
pub const Tree = struct {
    allocator: std.mem.Allocator,
    nodes: []Node,
    pub fn deinit(tree: *Tree) void {
        for (tree.nodes) |*n| n.children.deinit();
        tree.allocator.free(tree.nodes);
    }
    pub fn root(tree: Tree) ?*Node {
        return if (tree.nodes.len == 0) null else &tree.nodes[0];
    }
};
pub fn build(a: std.mem.Allocator, records: []const Record) !Tree {
    const nodes = try a.alloc(Node, records.len);
    for (nodes, 0..) |*n, i| n.* = .{ .id = i, .children = std.array_list.Managed(*Node).init(a) };
    var tree = Tree{ .allocator = a, .nodes = nodes };
    errdefer tree.deinit();
    const seen = try a.alloc(bool, records.len);
    defer a.free(seen);
    @memset(seen, false);
    for (records) |r| {
        if (r.id >= records.len) return error.NonContinuous;
        if (seen[r.id]) return error.DuplicateId;
        seen[r.id] = true;
        if (r.id == 0 and r.parent != 0) return error.InvalidRoot;
        if (r.id > 0 and r.parent >= r.id) return error.InvalidParent;
        if (r.id > 0) try nodes[r.parent].children.append(&nodes[r.id]);
    }
    for (nodes) |*n| std.mem.sort(*Node, n.children.items, {}, struct {
        fn less(_: void, x: *Node, y: *Node) bool {
            return x.id < y.id;
        }
    }.less);
    return tree;
}

