// Test scenarios adapted from the MIT-licensed Exercism Python track and
// exercism/problem-specifications (4289d4ec9ed947cd785939ab82c479bb8d4f2cc7).
const std = @import("std");
const t = std.testing;
const m = @import("tree_building.zig");
test "unordered records and ordered children" {
    var tree = try m.build(t.allocator, &.{ .{ .id = 2, .parent = 0 }, .{ .id = 0, .parent = 0 }, .{ .id = 1, .parent = 0 }, .{ .id = 3, .parent = 1 } });
    defer tree.deinit();
    const r = tree.root().?;
    try t.expectEqual(@as(usize, 2), r.children.items.len);
    try t.expectEqual(@as(usize, 1), r.children.items[0].id);
    try t.expectEqual(@as(usize, 3), r.children.items[0].children.items[0].id);
}
test "empty and malformed" {
    var tree = try m.build(t.allocator, &.{});
    defer tree.deinit();
    try t.expect(tree.root() == null);
    try t.expectError(error.InvalidRoot, m.build(t.allocator, &.{.{ .id = 0, .parent = 1 }}));
    try t.expectError(error.NonContinuous, m.build(t.allocator, &.{.{ .id = 1, .parent = 0 }}));
    try t.expectError(error.InvalidParent, m.build(t.allocator, &.{ .{ .id = 0, .parent = 0 }, .{ .id = 1, .parent = 1 } }));
    try t.expectError(error.DuplicateId, m.build(t.allocator, &.{ .{ .id = 0, .parent = 0 }, .{ .id = 0, .parent = 0 } }));
}
const ExpectedNode = struct { id: usize, children: []const *const ExpectedNode = &.{} };
fn sameBuilt(a: *const m.Node, b: *const ExpectedNode) anyerror!void {
    try t.expectEqual(b.id, a.id);
    try t.expectEqual(b.children.len, a.children.items.len);
    for (a.children.items, b.children) |x, y| try sameBuilt(x, y);
}
